import { isCliControlCommand } from './commandNames';
import { getPluginName } from '../hosts/pluginContext';

export const runControlPlane = async (
  args: string[] = process.argv.slice(2),
): Promise<void> => {
  if (args.includes('--no-telemetry'))
    process.env.RIVET_TELEMETRY_DISABLED = '1';
  const { redirectLogsToStderr } = await import('../utils/logger');
  redirectLogsToStderr();
  if (!isCliControlCommand(args[0])) {
    const { main } = await import('../index');
    return main(args);
  }
  if (
    !getPluginName() &&
    !['__serve', '__hub', 'update', 'stop', 'auth', 'version'].includes(args[0])
  ) {
    const { synchronizeRuntimes } = await import('./synchronizeRuntimes');
    const { processCliIO, emitResult } = await import('./io');
    const { errorResult } = await import('./envelope');
    const runtimes = await synchronizeRuntimes({ args, io: processCliIO });
    if (runtimes.failures.length > 0) {
      const message =
        'Rivet could not upgrade all running servers. Retry after resolving the reported runtime failures.';
      if (args[0] === 'mcp')
        throw new Error(
          `${message} ${runtimes.failures.map((failure) => failure.message).join(' ')}`,
        );
      const exitCode = emitResult(
        processCliIO,
        errorResult(
          args[0],
          'SERVER_UNAVAILABLE',
          message,
          { runtimes },
          { isRecoverable: true },
        ),
      );
      process.stdout.write('', () => process.exit(exitCode));
      return;
    }
  }
  const { runCliControlCommand } = await import('./router');
  const exitCode = await runCliControlCommand(args);
  process.stdout.write('', () => process.exit(exitCode));
};
